#!/usr/bin/env bash
# Ubuntu 24.04. Idempotent preparation; no game world or EULA is created here.
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive
if [[ $EUID -ne 0 ]]; then echo 'Run as root.' >&2; exit 1; fi
if [[ ! -s /etc/fogata/agent.env ]]; then echo 'Missing protected agent configuration.' >&2; exit 1; fi
# Only source a root-owned config generated by deployment, never a network payload.
set -a
source /etc/fogata/agent.env
set +a
: "${PANEL_HOSTNAME:?Set the Azure public IP DNS hostname}"
: "${ADMIN_CIDR:?Set the administrator public IPv4 CIDR}"
if [[ ! "$PANEL_HOSTNAME" =~ ^[a-zA-Z0-9.-]+$ ]]; then echo 'Invalid hostname' >&2; exit 1; fi
if [[ ! "$ADMIN_CIDR" =~ ^[0-9.]+/32$ ]]; then echo 'Invalid admin CIDR' >&2; exit 1; fi
# Panel and Wings share a VM. Resolve their own TLS hostname over loopback,
# avoiding a round trip through the public Azure IP while networking settles.
python3 - "$PANEL_HOSTNAME" <<'PY'
from pathlib import Path
import sys
p = Path('/etc/hosts')
lines = [line for line in p.read_text().splitlines() if '# fogata-panel-loopback' not in line]
lines.append('127.0.0.1 ' + sys.argv[1] + ' # fogata-panel-loopback')
p.write_text('\n'.join(lines) + '\n')
PY
apt-get update -qq
apt-get install -y ca-certificates curl gnupg unzip tar software-properties-common python3 python3-yaml git
if ! command -v php8.4 >/dev/null; then
  add-apt-repository -y ppa:ondrej/php
  apt-get update -qq
fi
apt-get install -y php8.4-cli php8.4-fpm php8.4-gd php8.4-mysql php8.4-mbstring php8.4-bcmath \
  php8.4-xml php8.4-curl php8.4-zip php8.4-intl php8.4-sqlite3 composer
install -d -m 0755 /etc/apt/keyrings
if ! command -v docker >/dev/null; then
  curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  . /etc/os-release
  printf 'deb [arch=%s signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/ubuntu %s stable\n' \
    "$(dpkg --print-architecture)" "$VERSION_CODENAME" > /etc/apt/sources.list.d/docker.list
  apt-get update -qq
  apt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin
fi
if ! command -v caddy >/dev/null; then
  apt-get install -y debian-keyring debian-archive-keyring apt-transport-https
  curl -fsSL https://dl.cloudsmith.io/public/caddy/stable/gpg.key | gpg --dearmor --yes -o /etc/apt/keyrings/caddy.gpg
  printf 'deb [signed-by=/etc/apt/keyrings/caddy.gpg] https://dl.cloudsmith.io/public/caddy/stable/deb/debian any-version main\n' > /etc/apt/sources.list.d/caddy.list
  apt-get update -qq
  apt-get install -y caddy
fi
install -d -o www-data -g www-data /var/www/pelican
# Resolve release versions once and record installed tags. Re-running preserves them.
# Operators can pin exact versions with PELICAN_VERSION/WINGS_VERSION before first install.
release_tag() {
  curl -fsSL -H 'Accept: application/vnd.github+json' "https://api.github.com/repos/$1/releases/latest" \
    | python3 -c 'import sys,json; print(json.load(sys.stdin)["tag_name"])'
}
if [[ ! -f /var/www/pelican/artisan ]]; then
  PELICAN_VERSION="${PELICAN_VERSION:-$(release_tag pelican/panel)}"
  curl -fL "https://github.com/pelican/panel/releases/download/${PELICAN_VERSION}/panel.tar.gz" -o /tmp/fogata-panel.tar.gz
  tar -xzf /tmp/fogata-panel.tar.gz -C /var/www/pelican
  printf '%s\n' "$PELICAN_VERSION" > /etc/fogata/panel-version
  rm -f /tmp/fogata-panel.tar.gz
fi
if [[ ! -f /etc/fogata/composer-complete ]]; then
  install -d -m 0700 /var/cache/fogata/composer
  (cd /var/www/pelican && COMPOSER_HOME=/var/cache/fogata/composer COMPOSER_ALLOW_SUPERUSER=1 \
    php8.4 /usr/bin/composer install --no-dev --optimize-autoloader --no-interaction)
  touch /etc/fogata/composer-complete
fi
chown -R www-data:www-data /var/www/pelican
if [[ ! -x /usr/local/bin/wings ]]; then
  WINGS_VERSION="${WINGS_VERSION:-$(release_tag pelican/wings)}"
  curl -fL "https://github.com/pelican/wings/releases/download/${WINGS_VERSION}/wings_linux_amd64" -o /usr/local/bin/wings
  chmod 0755 /usr/local/bin/wings
  printf '%s\n' "$WINGS_VERSION" > /etc/fogata/wings-version
fi
install -d /etc/pelican /var/run/wings
if [[ -f /etc/fogata/panel-public ]]; then
  SETUP_GUARD='@installer path /installer /installer/*
    respond @installer 404'
else
  SETUP_GUARD="@outsideAdmin not remote_ip ${ADMIN_CIDR} 127.0.0.1 ::1
    respond @outsideAdmin 403"
fi
cat > /etc/caddy/Caddyfile <<EOF
${PANEL_HOSTNAME} {
    # FOGATA_SETUP_BEGIN
    ${SETUP_GUARD}
    # FOGATA_SETUP_END
    root * /var/www/pelican/public
    php_fastcgi unix//run/php/php8.4-fpm.sock
    file_server
    encode gzip
    header X-Content-Type-Options nosniff
    @private path /.env /.git/* /storage/*
    respond @private 404
}
${PANEL_HOSTNAME}:8443 {
    reverse_proxy 127.0.0.1:8080
}
EOF
cat > /usr/local/sbin/fogata-open-panel <<'SCRIPT'
#!/usr/bin/env bash
set -euo pipefail
if [[ $EUID -ne 0 || "${1:-}" != '--confirm-setup-complete' ]]; then
  echo 'Complete the installer and create your administrator first. Then run: sudo fogata-open-panel --confirm-setup-complete' >&2
  exit 1
fi
python3 - <<'PY'
from pathlib import Path
p = Path('/etc/caddy/Caddyfile')
text = p.read_text()
begin, end = '    # FOGATA_SETUP_BEGIN\n', '    # FOGATA_SETUP_END\n'
prefix, rest = text.split(begin, 1)
_, suffix = rest.split(end, 1)
p.write_text(prefix + begin + '    @installer path /installer /installer/*\n    respond @installer 404\n' + end + suffix)
PY
caddy validate --config /etc/caddy/Caddyfile
systemctl reload caddy
touch /etc/fogata/panel-public
echo 'Panel opened over HTTPS. Installer permanently blocked by Caddy.'
SCRIPT
chmod 0755 /usr/local/sbin/fogata-open-panel
cat > /etc/systemd/system/wings.service <<'EOF'
[Unit]
Description=Pelican Wings
After=docker.service
Requires=docker.service
ConditionPathExists=/etc/pelican/config.yml
[Service]
User=root
WorkingDirectory=/etc/pelican
ExecStart=/usr/local/bin/wings
Restart=on-failure
RestartSec=5
LimitNOFILE=4096
[Install]
WantedBy=multi-user.target
EOF
cat > /etc/systemd/system/pelican-queue.service <<'EOF'
[Unit]
Description=Pelican queue worker
After=network-online.target
ConditionPathExists=/var/www/pelican/.env
[Service]
User=www-data
Group=www-data
WorkingDirectory=/var/www/pelican
ExecStart=/usr/bin/php8.4 artisan queue:work --sleep=3 --tries=3
Restart=always
RestartSec=10
[Install]
WantedBy=multi-user.target
EOF
cat > /etc/cron.d/pelican <<'EOF'
* * * * * www-data cd /var/www/pelican && /usr/bin/php8.4 artisan schedule:run >> /dev/null 2>&1
EOF
cat > /etc/systemd/system/fogata-agent.service <<'EOF'
[Unit]
Description=Fogata Minecraft heartbeat and graceful shutdown
After=network-online.target docker.service wings.service
Wants=network-online.target
[Service]
User=root
ExecStart=/usr/bin/python3 /opt/fogata/agent.py
Restart=always
RestartSec=10
UMask=0077
[Install]
WantedBy=multi-user.target
EOF
chmod 0600 /etc/fogata/agent.env
systemctl daemon-reload
usermod -a -G www-data caddy
systemctl enable --now docker php8.4-fpm caddy fogata-agent
systemctl restart caddy
systemctl enable wings pelican-queue
# The official web installer must be completed before starting Wings/queue.
touch /etc/fogata/bootstrap-complete
echo "Preparation complete. Finish Pelican web installer at https://${PANEL_HOSTNAME}/installer"
